cd /testbed && python -c "
import requests

# Should raise InvalidURL
for url in ['http://.example.com', 'http://example..com']:
    try:
        requests.get(url, timeout=2)
        print(f'{url}: No error (unexpected)')
    except requests.exceptions.InvalidURL as e:
        print(f'{url}: InvalidURL (correct)')
    except Exception as e:
        print(f'{url}: {type(e).__name__} (wrong)')

# Should work normally
try:
    r = requests.get('http://example.com', timeout=5)
    print(f'http://example.com: OK (correct)')
except requests.exceptions.InvalidURL:
    print(f'http://example.com: InvalidURL (wrong)')
except Exception as e:
    print(f'http://example.com: {type(e).__name__}')
"

